const rawOutput = String($node["Consultation"].json.output || "");
let parsedAI = {};
let cleanMessage = "";

function stripMarkdown(text) {
  return String(text || "")
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();
}

function tryParseJson(text) {
  try {
    return JSON.parse(stripMarkdown(text));
  } catch {
    return null;
  }
}

function looksLikeTechnicalPayload(text) {
  const t = String(text || "").trim();

  if (!t) return true;

  if ((t.startsWith("{") && t.endsWith("}")) || (t.startsWith("[") && t.endsWith("]"))) {
    return true;
  }

  if (
    /"text_to_user"\s*:|"consultation_status"\s*:|"recommended_next_step"\s*:|"result_summary"\s*:|"message_sent"\s*:/i.test(t)
  ) {
    return true;
  }

  return false;
}

function extractTextToUser(value) {
  if (!value) return "";

  if (typeof value === "string") {
    const trimmed = stripMarkdown(value);

    const parsed = tryParseJson(trimmed);
    if (parsed && typeof parsed === "object") {
      return extractTextToUser(parsed);
    }

    const jsonMatch = trimmed.match(/\{[\s\S]*"text_to_user"[\s\S]*\}/);
    if (jsonMatch) {
      const nestedParsed = tryParseJson(jsonMatch[0]);
      if (nestedParsed && typeof nestedParsed === "object") {
        return extractTextToUser(nestedParsed);
      }
    }

    return trimmed;
  }

  if (Array.isArray(value)) {
    for (const item of value) {
      const extracted = extractTextToUser(item);
      if (extracted) return extracted;
    }
    return "";
  }

  if (typeof value === "object") {
    if (typeof value.text_to_user === "string" && value.text_to_user.trim()) {
      return value.text_to_user.trim();
    }

    if (typeof value.message === "string" && value.message.trim()) {
      return value.message.trim();
    }

    if (typeof value.output === "string" && value.output.trim()) {
      return extractTextToUser(value.output);
    }

    if (typeof value.text === "string" && value.text.trim()) {
      return extractTextToUser(value.text);
    }
  }

  return "";
}

// 1. Пробуем распарсить верхний уровень
const cleanJson = stripMarkdown(rawOutput);
const topLevelParsed = tryParseJson(cleanJson);

if (topLevelParsed) {
  parsedAI = topLevelParsed;
} else {
  parsedAI = {};
}

// 2. Достаем именно пользовательский текст
cleanMessage = extractTextToUser(parsedAI) || extractTextToUser(rawOutput);

// 3. Если после всех попыток все еще техничка, даем мягкий fallback
if (!cleanMessage || looksLikeTechnicalPayload(cleanMessage)) {
  cleanMessage = "Подобрал варианты под ваш запрос. Могу сразу сузить до одного наиболее подходящего варианта: больше про мягкую ежедневную поддержку или больше про энергию и бодрость?";
}

// 4. Нормализуем статус
const aiStatus = String(parsedAI.consultation_status || parsedAI.status || "").toLowerCase();
const aiNextStep = String(parsedAI.recommended_next_step || "").toLowerCase();

const handoffByText =
  /переда[её]м? менеджер|переда[её]т[сc]я менеджер|передаю запрос|следующему специалисту|передан менеджеру|передаем специалисту/i.test(cleanMessage) ||
  cleanMessage.toLowerCase().includes("рассчитать изготовление");

const isCompleted =
  aiStatus === "completed" ||
  aiStatus === "handoff_required" ||
  aiNextStep === "human_handoff" ||
  handoffByText;

const normalizedStatus = isCompleted ? "completed" : "in_progress";
const recommendedStep = isCompleted ? "human_handoff" : "continue_consultation";
const needsHuman = isCompleted;

return {
  success: true,
  workflow_name: "Consultation_Workflow",
  lead_id: $node["When Executed by Another Workflow"].json.lead_id,

  text_to_user: cleanMessage,

  status: normalizedStatus,
  consultation_status: normalizedStatus,
  recommended_next_step: recommendedStep,
  detected_intent: isCompleted ? "handoff_ready" : "continue_consultation",
  result_summary:
    parsedAI.result_summary ||
    (isCompleted
      ? "Консультация завершена, запрос передан менеджеру."
      : "Консультация продолжается."),
  flags: {
    needs_human: needsHuman,
    should_log_event: true,
    should_update_crm: true,
    output_sanitized: cleanMessage !== (parsedAI.text_to_user || "")
  },
  timestamp: new Date().toISOString()
};
